import pricing
calls=[]
orig=pricing.quote
def spy(items,discount_percent=0):
 calls.append((items,discount_percent)); return orig(items,discount_percent)
pricing.quote=spy
from api import handle
assert handle({'items':[{'qty':2,'price':101}],'discount_percent':50,'extra':1})=={'total_cents':101}
assert calls[-1][1]==50
assert handle({'items':[]})=={'total_cents':0} and calls[-1][1]==0
for bad in (None,[],{},True):
 try: handle(bad)
 except ValueError: pass
 else: raise AssertionError(repr(bad))
print('api-ok')

import copy, legacy
calls=[]
original=legacy.total
def spy(items):
 calls.append(copy.deepcopy(items)); return original(items)
legacy.total=spy
from pricing import quote
x=[{'qty':1,'price':1},{'qty':1,'price':1}]; before=copy.deepcopy(x)
assert quote(x,50)==1 and x==before and calls
assert quote([],0)==0
assert quote([{'qty':3,'price':10**30}],33)==(3*10**30*67)//100
assert quote([{'qty':1,'price':1}],100)==0
n=len(calls)
for bad in (None,{},'',(),[None],[{}],[{'qty':1}],[{'price':1}],[{'qty':-1,'price':1}],[{'qty':True,'price':1}],[{'qty':1,'price':False}],[{'qty':1,'price':1.0}]):
 try: quote(bad)
 except ValueError: pass
 else: raise AssertionError(repr(bad))
for bad in (True,False,-1,101,1.0,'1',None):
 try: quote(x,bad)
 except ValueError: pass
 else: raise AssertionError(repr(bad))
assert len(calls)==n
print('pricing-ok')

